// Package diagram renders Mermaid diagrams to SVG at build time with Pele
// (https://pele.run), so pages carry finished SVG and no diagram JavaScript.
//
// Pele's colors and fonts are CSS variables (--pele-bg, --pele-fg, ...), so
// themes restyle diagrams, including for dark mode, with CSS alone.
//
// The bundled script is generated by scripts/vendorjs from
// the version pinned in third_party/js; see third_party/README.md.
package diagram

import (
	"crypto/sha256"
	_ "embed"
	"encoding/hex"
	"errors"
	"fmt"
	"strings"

	"github.com/MohamedElashri/nida/internal/jsengine"
	"github.com/MohamedElashri/nida/third_party/goja"
)

//go:embed files/pele.global.js.gz
var peleSource []byte

var (
	pool  = jsengine.NewPool("Pele", peleSource, "pele.render")
	cache jsengine.Cache
)

// Error is a diagram that Pele cannot render.
type Error struct {
	// Code is Pele's error code: syntax, semantic, unsupported-diagram,
	// or limit.
	Code    string
	Message string
	// Line and Column count from 1 within the diagram source, or are 0 when
	// the problem has no position.
	Line, Column int
}

func (e *Error) Error() string {
	msg := strings.TrimSpace(e.Message)
	if e.Line > 0 && !strings.Contains(msg, fmt.Sprintf("line %d", e.Line)) {
		return fmt.Sprintf("mermaid diagram line %d: %s", e.Line, msg)
	}
	return "mermaid diagram: " + msg
}

// Options control the layout of a diagram.
type Options struct {
	// MaxWidth is the width, in pixels, available to the diagram. A wider
	// diagram wraps its labels or, for flowcharts and similar diagrams,
	// switches to a vertical layout when that is narrower. 0 keeps the
	// natural layout, which the browser scales down to fit.
	MaxWidth int
}

// Render returns the diagram as an SVG element. The same source and options
// always render to the same SVG.
func Render(source string, opts Options) (string, error) {
	sum := sha256.Sum256([]byte(source))
	hash := hex.EncodeToString(sum[:])
	key := fmt.Sprintf("%s/%d", hash, opts.MaxWidth)
	if svg, ok := cache.Get(key); ok {
		return svg, nil
	}
	var svg string
	err := pool.Run(func(vm *jsengine.VM) error {
		options := vm.NewObject()
		// The ID prefix keeps the accessibility IDs of different diagrams
		// on a page apart.
		_ = options.Set("idPrefix", "dg-"+hash[:10]+"-")
		if opts.MaxWidth > 0 {
			_ = options.Set("maxWidth", opts.MaxWidth)
			// Pele only changes direction below its breakpoint, which
			// defaults to phone widths. Raise it so any too-wide diagram
			// may turn.
			_ = options.Set("directionBreakpoint", opts.MaxWidth+1)
		}
		result, err := vm.Entry(goja.Undefined(), vm.ToValue(source), options)
		if err != nil {
			return err
		}
		value := result.ToObject(vm.Runtime).Get("svg")
		if value == nil {
			return errors.New("mermaid diagram: Pele returned no SVG")
		}
		svg = value.String()
		return nil
	})
	if err != nil {
		return "", diagramError(source, err)
	}
	cache.Put(key, svg)
	return svg, nil
}

func diagramError(source string, err error) error {
	if errors.Is(err, jsengine.ErrTimeout) {
		return &Error{Code: "limit", Message: "rendering " + err.Error()}
	}
	thrown := jsengine.Thrown(err)
	if thrown == nil {
		return err
	}
	if jsengine.String(thrown, "name") != "PeleError" {
		// A bug inside Pele rather than a problem with the diagram.
		return fmt.Errorf("mermaid diagram: Pele failed: %s", jsengine.String(thrown, "message"))
	}
	e := &Error{
		Code:    jsengine.String(thrown, "code"),
		Message: jsengine.String(thrown, "message"),
		Line:    jsengine.Int(thrown, "line"),
		Column:  jsengine.Int(thrown, "column"),
	}
	// At the end of input, Pele points past the last line and shows an
	// empty excerpt; say where the diagram stopped instead.
	if last := strings.Count(strings.TrimRight(source, "\n"), "\n") + 1; e.Line > last {
		if _, rest, ok := strings.Cut(e.Message, "\n^\n"); ok {
			e.Message = "Parse error at the end of the diagram: " + rest
		}
		e.Line, e.Column = 0, 0
	}
	return e
}
